# PUT /api/sheets/{sheetId}/claims/{claimId} — edit a claim's amount, date and note; refused like an add.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimEdited
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
# POST /api/sheets/{sheetId}/claims/{claimId}/open — move a claim to OPEN; refused (409) when its
# status does not allow it.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: move
move:
  class: net.officefloor.hq.app.claim.OpenClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: log
log:
  class: net.officefloor.hq.app.claim.LogClaimStatus
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimStatus
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
# POST /api/sheets/{sheetId}/claims/{claimId}/defer?until=yyyy-MM-dd — defer an OPEN claim until a date
# after the sheet's today; refused (409) when it is not OPEN, (400) for a date not after today, (423)
# for a claim dated in a closed period.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: defer
defer:
  class: net.officefloor.hq.app.claim.DeferClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveDeferral
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimDeferred
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
# POST /api/sheets/{sheetId}/today — change the sheet's today (the date everything on it goes by).
# With grace days set, the open periods past them are closed (auto=yes) before the rollup lines.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetToday
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.sheet.ApplySheetToday
  govern: [ transaction ]
  next: autoclose
autoclose:
  class: net.officefloor.hq.app.period.AutoClosePeriods
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
# GET /api/sheets/{sheetId}/claims — every claim on the sheet, newest first.
list:
  class: net.officefloor.hq.app.claim.ListClaims
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.claim;

import com.fasterxml.jackson.annotation.JsonIgnore;
import java.util.List;

/** A claim of a person: an amount (two decimals, as text), a date (yyyy-MM-dd), a note and a status
 *  (a {@link ClaimStatus} name), and its number on the sheet (given when opened and kept when voided;
 *  none while a draft: the sheet-wide number, or {@code <period>-<n>} while period numbering is in force), its settled due (fixed when settled; none otherwise, or when there was no rate), and
 *  who opened it (none while a draft), and whether its person's last statement bound it, with the
 *  figure it bound (none when it had none): a bound claim shows and totals that figure. A correction (a
 *  negative amount) keeps the number of the SETTLED claim of its person it corrects (none otherwise). */
public class Claim {
    private final long id;
    private final String sheetId;
    private long personId;
    private String amount;
    private String date;
    private String note;
    private String status;
    private String number;
    private String settledDue;
    private String openedBy;
    private boolean stated;
    private String statedDue;
    private String corrects;
    private String roundDate;
    private String dueBy;
    private List<String> log = List.of();
    private String deferredUntil;
    private boolean deferred;
    private int proofs;
    private String splitFrom;
    private boolean reversal;

    public Claim(long id, String sheetId, long personId, String amount, String date, String note,
            String status, String number, String settledDue, String openedBy) {
        this(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null);
    }

    public Claim(long id, String sheetId, long personId, String amount, String date, String note,
            String status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public void setPersonId(long personId) { this.personId = personId; }
    public String getAmount() { return amount; }
    public void setAmount(String amount) { this.amount = amount; }
    public String getDate() { return date; }
    public void setDate(String date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
    public String getNumber() { return number; }
    public void setNumber(String number) { this.number = number; }
    public String getSettledDue() { return settledDue; }
    /** Whether this change voided a SETTLED claim, reversing its frozen figure (not stored). */
    @JsonIgnore
    public boolean isReversal() { return reversal; }
    public void setReversal(boolean reversal) { this.reversal = reversal; }
    public void setSettledDue(String settledDue) { this.settledDue = settledDue; }

    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }

    public String getCorrects() { return corrects; }
    public void setCorrects(String corrects) { this.corrects = corrects; }

    /** The date its figures round by (see {@link Dues.Late#rounding}): its own date, or for a
     *  correction the date of the claim it corrects. */
    public String getRoundDate() { return roundDate == null ? date : roundDate; }
    public void setRoundDate(String roundDate) { this.roundDate = roundDate; }

    /** Its due-by (yyyy-MM-dd), fixed when it was added: its date then plus the terms of its
     *  person's grade in force on that date. */
    public String getDueBy() { return dueBy; }
    public void setDueBy(String dueBy) { this.dueBy = dueBy; }

    /** Its status log, oldest first (see {@link ClaimLogRepository}). */
    public List<String> getLog() { return log; }
    public void setLog(List<String> log) { this.log = log; }

    /** The date it was last deferred until (yyyy-MM-dd; none: never deferred). */
    public String getDeferredUntil() { return deferredUntil; }

    /** Whether it is deferred on the sheet's today: OPEN and deferred until a later date. A deferred
     *  claim counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferred() { return deferred; }

    public void setDeferral(String deferredUntil, boolean deferred) {
        this.deferredUntil = deferredUntil;
        this.deferred = deferred;
    }

    /** Defer it until a date after the sheet's today. */
    public void defer(String until) {
        setDeferral(until, true);
    }

    /** How many proofs it has (0 until one is added). */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }

    /** The number of the claim it was split from (none: not split off a claim). */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }

    public boolean isStated() { return stated; }
    public String getStatedDue() { return statedDue; }

    /** Bind to a figure (null: none), or unbind when not {@code stated}. */
    public void bind(boolean stated, String statedDue) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
    }

    /** Whether it counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED do. */
    @JsonIgnore
    public boolean isCounting() {
        return ClaimStatus.isOpen(status) || ClaimStatus.SETTLED.name().equals(status);
    }

    /** Whether a statement's figure binds it now: it was bound to one and is not PENDING (a PENDING
     *  claim keeps its binding, but shows and totals its live figure until it is rejected). */
    @JsonIgnore
    public boolean isBound() {
        return stated && statedDue != null && !ClaimStatus.PENDING.name().equals(status);
    }

    /** The due it shows: the one fixed when settled, else the one bound by a statement (not while
     *  PENDING), else {@code live} (the amount at the rate in force on its date; null: none). */
    public String due(String live) {
        if (settledDue != null) return settledDue;
        return stated && !ClaimStatus.PENDING.name().equals(status) ? statedDue : live;
    }

    /** The audit suffix: {@code " number=<n>"} for a claim that has a number. */
    @JsonIgnore
    public String getAuditNumber() {
        return number == null ? "" : " number=" + number;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.List;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class ClaimRepository {

    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, number, settled_due, opened_by, stated, stated_due, corrects, due_by, deferred_until, proofs, split_from, "
            // Deferred now: OPEN and deferred until a date after the sheet's today.
            + "(status = 'OPEN' AND deferred_until IS NOT NULL AND deferred_until > "
            + "(SELECT s.today FROM sheet s WHERE s.id = claim.sheet_id)) AS deferred, "
            // The date it rounds by: a correction's is the date of the claim it corrects.
            + "COALESCE((SELECT k.claim_date FROM claim k WHERE k.sheet_id = claim.sheet_id AND k.number = claim.corrects), "
            + "claim_date) AS round_date";

    private static final RowMapper<Claim> ROW = (rs, n) -> withCorrects(new Claim(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getLong("person_id"),
            rs.getBigDecimal("amount").setScale(2).toPlainString(),
            rs.getObject("claim_date", LocalDate.class).toString(), rs.getString("note"),
            rs.getString("status"), rs.getString("number"),
            rs.getBigDecimal("settled_due") == null ? null
                    : rs.getBigDecimal("settled_due").setScale(2).toPlainString(),
            rs.getString("opened_by"), rs.getBoolean("stated"),
            rs.getBigDecimal("stated_due") == null ? null
                    : rs.getBigDecimal("stated_due").setScale(2).toPlainString()), rs.getString("corrects"),
            rs.getObject("round_date", LocalDate.class).toString(),
            rs.getObject("due_by", LocalDate.class).toString(),
            rs.getObject("deferred_until", LocalDate.class), rs.getBoolean("deferred"), rs.getInt("proofs"), rs.getString("split_from"));

    private static Claim withCorrects(Claim claim, String corrects, String roundDate, String dueBy,
            LocalDate deferredUntil, boolean deferred, int proofs, String splitFrom) {
        claim.setSplitFrom(splitFrom);
        claim.setProofs(proofs);
        claim.setCorrects(corrects);
        claim.setDeferral(deferredUntil == null ? null : deferredUntil.toString(), deferred);
        claim.setDueBy(dueBy);
        claim.setRoundDate(roundDate);
        return claim;
    }

    /** The next place in a sheet's list (newest first); takes the sheet id as its parameter. */
    private static final String NEXT_SEQ = "(SELECT COALESCE(MAX(k.list_seq), 0) + 1 FROM claim k WHERE k.sheet_id = ?)";

    private final JdbcTemplate jdbc;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY list_seq DESC, id DESC",
                ROW, sheetId);
    }

    public Claim find(String sheetId, long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?",
                ROW, sheetId, id).stream().findFirst().orElse(null);
    }

    /** The claim on the sheet with that number; null when none has it. */
    public Claim findByNumber(String sheetId, String number) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND number = ?",
                ROW, sheetId, number).stream().findFirst().orElse(null);
    }

    /** Add a claim with its due-by, fixed now. */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, LocalDate dueBy, String user) {
        GeneratedKeyHolder key = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, created_by, corrects, due_by) "
                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setObject(4, date);
            ps.setString(5, note);
            ps.setString(6, user);
            ps.setObject(7, corrects);
            ps.setObject(8, dueBy);
            return ps;
        }, key);
        long id = key.getKey().longValue();
        jdbc.update("UPDATE claim SET list_seq = " + NEXT_SEQ + " WHERE sheet_id = ? AND id = ?", sheetId, sheetId, id);
        return find(sheetId, id);
    }

    public void update(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, settled_due = ?, opened_by = ?, corrects = ? WHERE sheet_id = ? AND id = ?",
                new BigDecimal(claim.getAmount()), LocalDate.parse(claim.getDate()), claim.getNote(),
                claim.getStatus(), claim.getNumber(),
                claim.getSettledDue() == null ? null : new BigDecimal(claim.getSettledDue()),
                claim.getOpenedBy(), claim.getCorrects(),
                claim.getSheetId(), claim.getId());
    }

    /** Save a claim moved to another person: its person, its binding (dropped), and its place in the
     *  list, now the newest. */
    public void reassign(Claim claim) {
        jdbc.update("UPDATE claim SET person_id = ?, stated = ?, stated_due = ?, list_seq = " + NEXT_SEQ
                + " WHERE sheet_id = ? AND id = ?",
                claim.getPersonId(), claim.isStated(),
                claim.getStatedDue() == null ? null : new BigDecimal(claim.getStatedDue()),
                claim.getSheetId(), claim.getSheetId(), claim.getId());
    }

    /** Save a re-dated claim: its date and its number (a new one when its period changed). */
    public void redate(Claim claim) {
        jdbc.update("UPDATE claim SET claim_date = ?, number = ? WHERE sheet_id = ? AND id = ?",
                LocalDate.parse(claim.getDate()), claim.getNumber(), claim.getSheetId(), claim.getId());
    }

    /** The person's claims, newest first. */
    public List<Claim> listOf(String sheetId, long personId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY list_seq DESC, id DESC",
                ROW, sheetId, personId);
    }

    /** Save the date a claim is deferred until. */
    public void updateDeferral(Claim claim) {
        jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet_id = ? AND id = ?",
                claim.getDeferredUntil() == null ? null : LocalDate.parse(claim.getDeferredUntil()),
                claim.getSheetId(), claim.getId());
    }

    /** Save the number of the claim a claim was split from. */
    public void updateSplitFrom(Claim claim) {
        jdbc.update("UPDATE claim SET split_from = ? WHERE sheet_id = ? AND id = ?",
                claim.getSplitFrom(), claim.getSheetId(), claim.getId());
    }

    /** Save a claim's proofs count. */
    public void updateProofs(Claim claim) {
        jdbc.update("UPDATE claim SET proofs = ? WHERE sheet_id = ? AND id = ?",
                claim.getProofs(), claim.getSheetId(), claim.getId());
    }

    /** Save a claim's binding by its person's last statement. */
    public void updateBinding(Claim claim) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
                claim.isStated(), claim.getStatedDue() == null ? null : new BigDecimal(claim.getStatedDue()),
                claim.getSheetId(), claim.getId());
    }

    /** The sheet's next claim number, taken in one atomic statement so two claims opened at the same
     *  moment never get the same one; rolled back with the request when it is refused. */
    public String nextNumber(String sheetId) {
        return String.valueOf(jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE ("
                + "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)",
                Long.class, sheetId));
    }

    /** The next number in a period's own sequence on the sheet ({@code <period>-<n>}, from 1), or
     *  for a claim in no period ({@code period} null) in the X sequence ({@code X-<n>}); taken
     *  atomically as {@link #nextNumber} is. */
    public String nextPeriodNumber(String sheetId, String period) {
        String key = period == null ? "" : period;
        try {
            jdbc.update("INSERT INTO sheet_period_number (sheet_id, period_key) SELECT ?, ? WHERE NOT EXISTS "
                    + "(SELECT 1 FROM sheet_period_number WHERE sheet_id = ? AND period_key = ?)",
                    sheetId, key, sheetId, key);
        } catch (DuplicateKeyException raced) {
            // Another request started the sequence at the same moment.
        }
        Long n = jdbc.queryForObject("SELECT last_number FROM FINAL TABLE (UPDATE sheet_period_number "
                + "SET last_number = last_number + 1 WHERE sheet_id = ? AND period_key = ?)",
                Long.class, sheetId, key);
        return (period == null ? "X" : period) + "-" + n;
    }
}
